import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, BadgeCheck, Bell, Camera, Check, CheckCircle2, ChevronDown, ChevronRight, CircleAlert, Clock3, Coins, Gift, Heart, History, Home, ImagePlus, Info, LayoutDashboard, MapPin, Megaphone, Menu, Minus, Plus, ReceiptText, RotateCcw, ScanLine, Search, Settings2, ShieldCheck, ShoppingBasket, ShoppingCart, SlidersHorizontal, Sparkles, Store as StoreIcon, Tag, TicketPercent, Trash2, TrendingDown, Upload, UserRound, Wallet, X } from 'lucide-react';
import { basePrices, categories, initialBasket, initialCoupons, lookup, money, normalize, products, seedPrices, stores, type BasketItem, type Claim, type Coupon, type Price, type Receipt, type ReceiptItem } from './data';

type ConsumerPage='home'|'compare'|'scan'|'alerts'|'benefits'|'basket'|'history'|'profile';
type MerchantPage='overview'|'coupons'|'ads'|'redeem'|'business';
type DraftRow={productId:string;label:string;qty:number;unitPrice:number};
const isoToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const nav=[{id:'home',text:'Inicio',icon:Home},{id:'compare',text:'Comparar',icon:SlidersHorizontal},{id:'scan',text:'Escanear',icon:ScanLine},{id:'alerts',text:'Alertas',icon:Bell},{id:'benefits',text:'Beneficios',icon:Gift}] as const;
const merchantNav=[{id:'overview',text:'Resumen',icon:LayoutDashboard},{id:'coupons',text:'Cupones',icon:TicketPercent},{id:'ads',text:'Publicidad',icon:Megaphone},{id:'redeem',text:'Canjes',icon:BadgeCheck},{id:'business',text:'Mi negocio',icon:StoreIcon}] as const;
const demoRows:DraftRow[]=[{productId:'leche',label:'LECHE ENTERA LALA 1L',qty:1,unitPrice:29.9},{productId:'huevos',label:'HUEVO SAN JUAN 12 PZ',qty:1,unitPrice:44.5},{productId:'arroz',label:'ARROZ VERDE VALLE 900G',qty:1,unitPrice:29.5}];
function useStored<T>(key:string,initial:T){const [value,setValue]=useState<T>(()=>{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw) as T:initial}catch{return initial}});useEffect(()=>{localStorage.setItem(key,JSON.stringify(value))},[key,value]);return[value,setValue]as const}
function Logo({compact=false}:{compact?:boolean}){return <div className="brand"><span className="brand-mark"><ShoppingBasket size={23} strokeWidth={2.4}/><span className="brand-spark">✦</span></span>{!compact&&<span className="brand-word">Ces<span>Tick</span><small>Compra más inteligente</small></span>}</div>}
function SectionTitle({eyebrow,title,action}:{eyebrow?:string;title:string;action?:React.ReactNode}){return <div className="section-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>}
function Empty({icon:Icon=ShoppingBasket,title,desc,action}:{icon?:typeof ShoppingBasket;title:string;desc:string;action?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={24}/></span><h3>{title}</h3><p>{desc}</p>{action}</div>}
function Pill({children,color='blue'}:{children:React.ReactNode;color?:'blue'|'green'|'amber'|'gray'}){return <span className={'pill pill-'+color}>{children}</span>}
function ProductArt({emoji,small=false}:{emoji:string;small?:boolean}){return <span className={'product-art '+(small?'small':'')}>{emoji}</span>}
function StoreAvatar({name,color}:{name:string;color:string}){return <span className="store-avatar" style={{'--store':color} as React.CSSProperties}>{name.charAt(0)}</span>}
function App(){
 const[mode,setMode]=useState<'consumer'|'merchant'>('consumer');const[page,setPage]=useState<ConsumerPage>('home');const[merchantPage,setMerchantPage]=useState<MerchantPage>('overview');const[mobileMenu,setMobileMenu]=useState(false);
 const[basket,setBasket]=useStored<BasketItem[]>('ct-basket-v2',initialBasket);const[receipts,setReceipts]=useStored<Receipt[]>('ct-receipts-v2',[]);const[observations,setObservations]=useStored<Price[]>('ct-prices-v2',[]);const[points,setPoints]=useStored<number>('ct-points-v2',184);const[coupons,setCoupons]=useStored<Coupon[]>('ct-coupons-v2',initialCoupons);const[claims,setClaims]=useStored<Claim[]>('ct-claims-v2',[]);const[followed,setFollowed]=useStored<string[]>('ct-follow-v2',['leche','huevos','arroz']);const[alertsSeen,setAlertsSeen]=useStored<boolean>('ct-alerts-seen-v2',false);
 const[toast,setToast]=useState('');const[category,setCategory]=useState('Todos');const[search,setSearch]=useState('');const[compareSort,setCompareSort]=useState<'price'|'coverage'>('price');const[scanState,setScanState]=useState<'upload'|'review'|'success'>('upload');const[scanImage,setScanImage]=useState('');const[scanSource,setScanSource]=useState('Demo guiada');const[scanBusy,setScanBusy]=useState(false);const[scanError,setScanError]=useState('');const[draftStore,setDraftStore]=useState<string>('chedraui');const[draftDate,setDraftDate]=useState(isoToday());const[draftRows,setDraftRows]=useState<DraftRow[]>(demoRows);const[lastEarned,setLastEarned]=useState(0);const[scanId,setScanId]=useState('');const[fileRef]=useState(()=>({current:null as HTMLInputElement|null}));
 const[showCoupon,setShowCoupon]=useState<Coupon|null>(null);const[merchantDraft,setMerchantDraft]=useState({name:'',title:'',minimum:'200',cost:'200',stock:'10',expires:'2026-12-31'});const[merchantMessage,setMerchantMessage]=useState('');const[merchantCode,setMerchantCode]=useState('');const[adActive,setAdActive]=useStored<boolean>('ct-ad-v2',true);
 const prices=useMemo(()=>{const m=new Map<string,Price>();seedPrices.forEach(p=>m.set(p.storeId+':'+p.productId,p));observations.forEach(p=>m.set(p.storeId+':'+p.productId,p));return m},[observations]);
 const priceFor=(productId:string,storeId:string)=>prices.get(storeId+':'+productId);
 const add=(id:string)=>setBasket(prev=>{const item=prev.find(x=>x.productId===id);return item?prev.map(x=>x.productId===id?{...x,qty:x.qty+1}:x):[...prev,{productId:id,qty:1}]});
 const qty=(id:string)=>basket.find(x=>x.productId===id)?.qty||0;
 const changeQty=(id:string,d:number)=>setBasket(prev=>prev.map(x=>x.productId===id?{...x,qty:x.qty+d}:x).filter(x=>x.qty>0));
 const notify=(message:string)=>{setToast(message);setTimeout(()=>setToast(''),3300)};
 const navigate=(next:ConsumerPage)=>{setMode('consumer');setPage(next);setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'})};
 const merchantNavigate=(next:MerchantPage)=>{setMode('merchant');setMerchantPage(next);setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'})};
 const summaries=useMemo(()=>stores.map(store=>{let total=0;let count=0;const items=basket.map(item=>{const found=prices.get(store.id+':'+item.productId);if(found){total+=found.value*item.qty;count++}return{item,found}});return{store,total,count,items,complete:count===basket.length&&basket.length>0}}).sort((a,b)=>compareSort==='price'?(a.complete===b.complete?a.total-b.total:Number(b.complete)-Number(a.complete)):(b.count-a.count||a.total-b.total)),[basket,prices,compareSort]);
 const comparable=summaries.filter(s=>s.complete);const maxComplete=comparable.length?Math.max(...comparable.map(s=>s.total)):0;const best=comparable[0];
 const latest=receipts.reduce((s,r)=>s+r.total,0);
 const allProducts=useMemo(()=>products.filter(p=>(category==='Todos'||p.category===category)&&normalize([p.name,p.brand,p.size,p.category].join(' ')).includes(normalize(search))),[category,search]);
 const pendingClaim=(id:string)=>claims.find(c=>c.couponId===id&&c.status==='reserved'&&(Date.now()-new Date(c.claimedAt).getTime())<86400000);
 useEffect(()=>{const overdue=claims.filter(c=>c.status==='reserved'&&Date.now()-new Date(c.claimedAt).getTime()>=86400000);if(!overdue.length)return;const expiredIds=new Set(overdue.map(c=>c.id));setClaims(prev=>prev.map(c=>expiredIds.has(c.id)?{...c,status:'expired' as const}:c));setPoints(prev=>prev+overdue.reduce((t,c)=>t+c.cost,0));setCoupons(prev=>prev.map(c=>({...c,claimed:Math.max(0,c.claimed-overdue.filter(x=>x.couponId===c.id).length)})));},[claims,setClaims,setCoupons,setPoints]);
 const claimCoupon=(c:Coupon)=>{if(c.expires<isoToday())return notify('Esta campaña ya venció.');if(points<c.cost)return notify('Necesitas más puntos para reclamar este cupón.');if(c.claimed>=c.stock)return notify('Ya no hay cupos disponibles.');if(pendingClaim(c.id))return notify('Ya tienes un cupón de esta campaña.');const code='CT-'+Math.random().toString(36).slice(2,8).toUpperCase();setPoints(p=>p-c.cost);setCoupons(prev=>prev.map(x=>x.id===c.id?{...x,claimed:x.claimed+1}:x));setClaims(prev=>[{id:crypto.randomUUID(),couponId:c.id,code,claimedAt:new Date().toISOString(),status:'reserved',cost:c.cost},...prev]);setShowCoupon(null);notify('¡Cupón reservado! Puedes ver tu código en Beneficios.');};
 const demoScan=()=>{setScanImage('');setScanSource('Demo guiada · lectura preparada');setDraftStore('chedraui');setDraftDate(isoToday());setDraftRows(demoRows);setScanId('DEMO-'+Date.now());setScanError('');setScanState('review')};
 const fileScan=async(f?:File)=>{if(!f)return;if(!f.type.startsWith('image/'))return setScanError('Selecciona una imagen JPG, PNG o WEBP.');setScanBusy(true);setScanError('');const reader=new FileReader();reader.onload=()=>setScanImage(String(reader.result||''));reader.readAsDataURL(f);try{const {recognize}=await import('tesseract.js');const out=await recognize(f,'spa+eng');const raw=out.data.text.toUpperCase();const found=products.filter(p=>normalize(raw).includes(normalize(p.name))).slice(0,8);const rows=found.map(p=>({productId:p.id,label:p.name+' '+p.brand,qty:1,unitPrice:basePrices[p.id]}));setDraftRows(rows.length?rows:[{productId:'',label:'ARTÍCULO POR IDENTIFICAR',qty:1,unitPrice:0}]);setDraftStore('');setDraftDate(isoToday());setScanSource('OCR real · requiere revisión manual');setScanId('OCR-'+Date.now());setScanState('review');if(!rows.length)setScanError('No se reconocieron productos del catálogo. Corrige los artículos antes de guardar.')}catch{setScanError('No fue posible realizar el OCR. Prueba con la demostración guiada.') }finally{setScanBusy(false)}};
 const updateDraft=(i:number,k:keyof DraftRow,v:string|number)=>setDraftRows(prev=>prev.map((r,j)=>j===i?{...r,[k]:v}:r));
 const saveReceipt=()=>{const valid=draftRows.filter(r=>r.productId&&r.qty>0&&r.unitPrice>0);if(!valid.length)return notify('Agrega al menos un producto identificado con precio válido.');const items:ReceiptItem[]=valid.map(r=>({productId:r.productId,label:r.label,qty:r.qty,unitPrice:r.unitPrice}));const total=items.reduce((s,x)=>s+x.qty*x.unitPrice,0);const signature=[draftStore||'desconocida',draftDate,...items.map(x=>x.productId+':'+x.qty+':'+x.unitPrice)].join('|');if(receipts.some(r=>r.fingerprint===signature))return notify('Este ticket ya está registrado; no genera puntos duplicados.');const distinct=new Set(items.map(x=>x.productId)).size;const dayCount=receipts.filter(r=>r.date===draftDate&&r.points>0).length;const weekCount=receipts.filter(r=>r.points>0&&(Date.now()-new Date(r.date).getTime())/(864e5)<=7).length;const within14=Math.abs(Date.now()-new Date(draftDate).getTime())/(864e5)<=14;const earned=within14&&dayCount<2&&weekCount<10?10+2*Math.min(distinct,5):0;const rec:Receipt={id:scanId||crypto.randomUUID(),merchant:stores.find(s=>s.id===draftStore)?.name||'Comercio no identificado',storeId:draftStore||null,date:draftDate,items,total,points:earned,source:scanSource,fingerprint:signature};setReceipts(prev=>[rec,...prev]);if(draftStore)setObservations(prev=>[...prev.filter(p=>!(p.storeId===draftStore&&items.some(i=>i.productId===p.productId))),...items.map(it=>({storeId:draftStore,productId:it.productId,value:it.unitPrice,date:draftDate,source:'Ticket revisado · demo'}))]);if(earned)setPoints(p=>p+earned);setLastEarned(earned);setScanState('success');notify(earned?'Compra registrada y puntos actualizados.':'Compra registrada en tu historial.')};
 const reset=()=>{if(!confirm('¿Restaurar todos los datos de demostración de CesTick?'))return;setBasket(initialBasket);setReceipts([]);setObservations([]);setPoints(184);setCoupons(initialCoupons);setClaims([]);setFollowed(['leche','huevos','arroz']);setAlertsSeen(false);setAdActive(true);navigate('home');notify('Se restauraron los datos de demostración.')};
 const makeCoupon=()=>{if(!merchantDraft.name.trim()||!merchantDraft.title.trim())return setMerchantMessage('Completa el nombre del negocio y la promoción.');const c:Coupon={id:crypto.randomUUID(),merchant:merchantDraft.name.trim(),title:merchantDraft.title.trim(),description:`En compra mínima de ${money(+merchantDraft.minimum||0)}.`,cost:+merchantDraft.cost||120,minimum:+merchantDraft.minimum||0,stock:Math.max(1,+merchantDraft.stock||1),claimed:0,expires:merchantDraft.expires,tag:'Nuevo comercio · demo',emoji:'🏪'};setCoupons(prev=>[c,...prev]);setMerchantDraft({name:'',title:'',minimum:'200',cost:'200',stock:'10',expires:'2026-12-31'});setMerchantMessage('Campaña de demostración publicada. Ya aparece en Beneficios.');};
 const redeem=()=>{const claim=claims.find(x=>x.code.toUpperCase()===merchantCode.trim().toUpperCase());if(!claim){setMerchantMessage('Código no encontrado. Comprueba que se haya reclamado desde Beneficios.');return}if(claim.status!=='reserved'||Date.now()-new Date(claim.claimedAt).getTime()>=86400000){setMerchantMessage('Este código ya fue usado o venció.');return}const camp=coupons.find(c=>c.id===claim.couponId);if(!camp||camp.expires<isoToday()){setMerchantMessage('La campaña ya no está vigente.');return}setClaims(prev=>prev.map(x=>x.id===claim.id?{...x,status:'used'}:x));setMerchantCode('');setMerchantMessage('Canje registrado correctamente (demostración).')};
 const openScan=()=>{setScanState('upload');navigate('scan')};
 const renderConsumer=()=>{
 if(page==='home')return <>
  <section className="editorial-hero"><div className="editorial-intro"><span className="intro-kicker"><span className="kicker-dot"/> TU DESPENSA, A TU MANERA</span><h1>Compra mejor.<br/><span>Compara con claridad.</span></h1><p>Prepara tu lista, compara el costo de tu despensa y aprovecha tus tickets para tomar mejores decisiones.</p><div className="hero-actions"><button className="button blue" onClick={()=>navigate('compare')}>Comparar mi despensa <ArrowRight size={17}/></button><button className="button quiet" onClick={openScan}><ScanLine size={18}/> Escanear ticket</button></div><span className="hero-caveat">Precios ilustrativos para el prototipo · Cancún, Q. Roo</span></div><div className="phone-stage" aria-hidden="true"><div className="phone-device"><div className="phone-camera"/><div className="phone-screen"><div className="phone-topline"><span>Mi canasta</span><ShoppingBasket size={15}/></div><div className="phone-total"><small>Tu lista de compras</small><strong>{basket.length} productos</strong></div><div className="phone-product"><span>🥛</span><div><b>Leche entera</b><small>1 L · 1 unidad</small></div><CheckCircle2 size={15}/></div><div className="phone-product"><span>🥚</span><div><b>Huevos</b><small>12 piezas · 1 paquete</small></div><CheckCircle2 size={15}/></div><div className="phone-product"><span>🍚</span><div><b>Arroz</b><small>900 g · 1 bolsa</small></div><CheckCircle2 size={15}/></div><div className="phone-result"><span>Compara tus opciones</span><b>Supermercados de Cancún</b><i/></div></div></div><div className="phone-note"><span className="phone-note-icon"><ReceiptText size={17}/></span><div><b>Tu ticket también cuenta</b><small>Registra compras y suma puntos</small></div></div></div></section>
  <section className="journey"><div className="journey-head"><span className="eyebrow">ASÍ FUNCIONA</span><h2>Todo empieza con tu lista.</h2><p>Sin pasos complicados. Las mismas compras que realizas ayudan a construir mejores comparaciones.</p></div><div className="journey-grid"><button onClick={()=>navigate('basket')} className="journey-step"><span className="step-num">01</span><ShoppingBasket size={27}/><b>Prepara tu canasta</b><small>Elige productos y ajusta cantidades.</small></button><button onClick={()=>navigate('compare')} className="journey-step"><span className="step-num">02</span><SlidersHorizontal size={27}/><b>Compara supermercados</b><small>Revisa precios y datos faltantes.</small></button><button onClick={openScan} className="journey-step"><span className="step-num">03</span><ReceiptText size={27}/><b>Registra tu ticket</b><small>Guarda tu compra y aporta datos.</small></button></div></section>
  <section className="home-summary-strip"><button onClick={()=>navigate('history')}><ReceiptText size={19}/><span><b>{receipts.length} tickets</b><small>Mis compras</small></span><ChevronRight size={17}/></button><button onClick={()=>navigate('basket')}><ShoppingBasket size={19}/><span><b>{basket.reduce((a,b)=>a+b.qty,0)} artículos</b><small>En mi canasta</small></span><ChevronRight size={17}/></button><button onClick={()=>navigate('benefits')}><Coins size={19}/><span><b>{points} puntos</b><small>Mis beneficios</small></span><ChevronRight size={17}/></button></section>
  <SectionTitle eyebrow="AHORRA CON INFORMACIÓN" title="Tu canasta, al mejor precio" action={<button className="text-action" onClick={()=>navigate('basket')}>Editar canasta <ArrowRight size={15}/></button>}/>
  <div className="feature-card"><div className="feature-head"><div><span className="eyebrow">COMPARACIÓN ESTIMADA</span><h3>{basket.length} productos seleccionados</h3><p>Precios de ejemplo con cobertura de sucursales en Cancún.</p></div><span className="feature-icon"><ShoppingCart size={28}/></span></div><div className="store-pick">{best?<><StoreAvatar name={best.store.name} color={best.store.color}/><div><small>Opción con canasta completa</small><strong>{best.store.name}</strong><span>{best.store.branch}</span></div><strong className="store-total">{money(best.total)}</strong></>:<span>Agrega productos o revisa los precios que faltan para comparar.</span>}</div><button className="button blue wide" onClick={()=>navigate('compare')}>Ver comparación completa <ArrowRight size={18}/></button></div>
  <div className="two-cols"><div><SectionTitle eyebrow="RECENTEMENTE" title="Tus últimas compras" action={<button className="text-action" onClick={()=>navigate('history')}>Ver todas <ArrowRight size={15}/></button>}/>{receipts.length?<div className="list-panel">{receipts.slice(0,3).map(r=><div className="transaction" key={r.id}><span className="transaction-icon"><ReceiptText/></span><div><b>{r.merchant}</b><small>{r.date} · {r.items.length} productos</small></div><strong>{money(r.total)}</strong></div>)}</div>:<div className="mini-empty"><ReceiptText size={29}/><strong>Tus compras aparecerán aquí</strong><small>Registra tu primer ticket para comenzar.</small><button className="text-action" onClick={openScan}>Escanear ahora <ArrowRight size={15}/></button></div>}</div><div><SectionTitle eyebrow="COMUNIDAD LOCAL" title="Beneficios para ti" action={<button className="text-action" onClick={()=>navigate('benefits')}>Explorar <ArrowRight size={15}/></button>}/><div className="reward-highlight"><span className="reward-emoji">☕</span><div><Pill>RECOMPENSAS DEMO</Pill><h3>Tu próxima recompensa te espera</h3><p>Convierte tus tickets en oportunidades con negocios locales.</p><button className="button white" onClick={()=>navigate('benefits')}>Ver beneficios <ArrowRight size={16}/></button></div></div></div></div>
 </>;
 if(page==='compare')return <><div className="page-head"><div><span className="eyebrow">PRECIOS CLAROS · DECISIONES MEJORES</span><h1>Compara tu despensa</h1><p>Arma una canasta y descubre dónde te conviene comprar.</p></div><button className="button subtle" onClick={()=>navigate('basket')}><ShoppingBasket size={18}/> Mi canasta <span className="count-dot">{basket.reduce((s,x)=>s+x.qty,0)}</span></button></div><div className="searchbar"><Search size={20}/><input aria-label="Buscar productos" placeholder="Busca leche, arroz, detergente..." value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="Limpiar búsqueda" onClick={()=>setSearch('')}><X size={17}/></button>}</div><div className="category-scroll">{categories.map(c=><button className={'category '+(category===c?'active':'')} onClick={()=>setCategory(c)} key={c}>{c}</button>)}</div><div className="page-split"><div><SectionTitle eyebrow={`${allProducts.length} PRODUCTOS EN CATÁLOGO`} title="Explora y agrega"/><div className="product-grid">{allProducts.map(p=>{const amounts=stores.map(s=>priceFor(p.id,s.id)?.value).filter((n):n is number=>typeof n==='number');const lowest=amounts.length?Math.min(...amounts):null;return <div className="product-card" key={p.id}><div className="product-top"><ProductArt emoji={p.emoji}/>{qty(p.id)>0&&<Pill color="green">En canasta</Pill>}</div><span className="product-category">{p.category}</span><h3>{p.name}</h3><p>{p.brand} · {p.size}</p><div className="product-footer"><div><small>Desde · demo</small><strong>{lowest===null?'Sin datos':money(lowest)}</strong></div><button className="square-add" onClick={()=>{add(p.id);notify(p.name+' agregado a tu canasta')}} aria-label={'Agregar '+p.name}><Plus size={20}/></button></div></div>})}</div>{!allProducts.length&&<Empty icon={Search} title="Sin coincidencias" desc="Prueba otra marca, producto o categoría."/>}</div><div className="compare-side"><div className="sticky-panel"><SectionTitle eyebrow="CÁLCULO DINÁMICO" title="Comparación de tu canasta"/><p className="muted small">Precios por sucursal · los faltantes no se inventan</p><div className="segment"><button className={compareSort==='price'?'on':''} onClick={()=>setCompareSort('price')}>Menor total</button><button className={compareSort==='coverage'?'on':''} onClick={()=>setCompareSort('coverage')}>Cobertura</button></div>{basket.length?summaries.map((s,i)=><div className={'compare-store '+(s.complete&&i===0?'winner':'')} key={s.store.id}><div className="compare-store-top"><StoreAvatar name={s.store.name} color={s.store.color}/><div><b>{s.store.name}</b><small>{s.store.branch}</small></div>{s.complete&&i===0&&<Pill color="green">Mejor opción</Pill>}</div><div className="store-comparison"><strong>{money(s.total)}{!s.complete&&<sup>*</sup>}</strong><span>{s.count}/{basket.length} productos</span></div>{!s.complete&&<p className="missing-note">* Total parcial; faltan {basket.length-s.count} precios.</p>}{s.complete&&maxComplete>s.total&&<span className="savings-tag"><TrendingDown size={14}/> Hasta {money(maxComplete-s.total)} menos que otra canasta completa</span>}</div>):<Empty title="Tu canasta está vacía" desc="Agrega productos para calcular los totales."/>}<button className="button blue wide" onClick={()=>navigate('basket')}>Editar cantidades <ArrowRight size={16}/></button><p className="footnote"><Info size={15}/> Los precios iniciales son ficticios. Los tickets revisados con sucursal identificada reemplazan las observaciones correspondientes.</p></div></div></div></>;
 if(page==='basket')return <><div className="page-head"><div><span className="eyebrow">ORGANIZA TUS COMPRAS</span><h1>Mi canasta</h1><p>Ajusta cantidades antes de comparar tus supermercados.</p></div><button className="button subtle" onClick={()=>navigate('compare')}><Plus size={17}/> Agregar productos</button></div><div className="content-narrow">{basket.length?<><div className="list-panel">{basket.map(item=>{const p=lookup(item.productId);if(!p)return null;return <div className="basket-row" key={item.productId}><ProductArt emoji={p.emoji} small/><div className="basket-product"><b>{p.name}</b><small>{p.brand} · {p.size}</small></div><div className="quantity"><button aria-label="Quitar uno" onClick={()=>changeQty(p.id,-1)}><Minus size={16}/></button><strong>{item.qty}</strong><button aria-label="Añadir uno" onClick={()=>changeQty(p.id,1)}><Plus size={16}/></button></div><button className="icon-button danger" aria-label="Eliminar producto" onClick={()=>setBasket(prev=>prev.filter(x=>x.productId!==p.id))}><Trash2 size={17}/></button></div>})}</div><div className="basket-actions"><span>{basket.reduce((s,i)=>s+i.qty,0)} artículos · {basket.length} productos distintos</span><button className="button blue" onClick={()=>navigate('compare')}>Comparar mi canasta <ArrowRight size={18}/></button></div></>:<Empty title="Tu canasta aún está vacía" desc="Elige los productos que necesitas para descubrir dónde conviene comprarlos." action={<button className="button blue" onClick={()=>navigate('compare')}>Explorar productos</button>}/>}</div></>;
 if(page==='scan')return <><div className="page-head"><div><span className="eyebrow">CADA TICKET CUENTA</span><h1>Escanea tu ticket</h1><p>Guarda tus compras, contribuye con precios y suma puntos.</p></div><Pill color="blue">Hasta 20 pts por ticket válido</Pill></div><div className="scan-steps">{['Captura','Revisión','Registro'].map((s,i)=><div className={'scan-step '+((scanState==='upload'?0:scanState==='review'?1:2)>=i?'active':'')} key={s}><span>{i+1}</span><b>{s}</b></div>)}</div>{scanState==='upload'?<div className="content-narrow"><div className="upload-card"><span className="upload-icon"><ScanLine size={37}/></span><h2>Tu ticket tiene información valiosa</h2><p>Sube una foto legible de tu compra. Intentaremos reconocer los artículos con OCR para que puedas revisarlos.</p><div className="upload-drop"><ImagePlus size={35}/><h3>Arrastra o selecciona tu imagen</h3><p>JPG, PNG o WEBP · luz natural y texto legible</p><input ref={node=>{fileRef.current=node}} type="file" accept="image/*" aria-label="Seleccionar imagen de ticket" onChange={e=>{void fileScan(e.target.files?.[0]);e.target.value=''}}/><button className="button blue" disabled={scanBusy} onClick={()=>fileRef.current?.click()}><Upload size={17}/>{scanBusy?'Procesando OCR...':'Subir ticket'}</button></div><div className="or-divider">o</div><button className="button subtle wide" onClick={demoScan}><Sparkles size={18}/> Probar con un ticket preparado</button><p className="footnote centered">La demostración guiada permite probar el recorrido completo sin fotografía.</p></div>{scanError&&<div className="notice error"><CircleAlert size={18}/>{scanError}</div>}</div>:scanState==='review'?<div className="review-layout"><div className="panel"><SectionTitle eyebrow="PASO 2 DE 3" title="Revisa tu lectura"/><p className="muted">Corrige productos e importes antes de registrar. Los datos de OCR requieren supervisión.</p>{scanImage?<img className="receipt-preview" src={scanImage} alt="Imagen del ticket seleccionado"/>:<div className="demo-ticket"><ReceiptText size={38}/><strong>TICKET DE DEMOSTRACIÓN</strong><span>{stores.find(s=>s.id===draftStore)?.name||'Sucursal desconocida'}</span><small>Tres productos preparados para demostrar el flujo.</small></div>}<Pill color={scanSource.includes('Demo')?'amber':'blue'}>{scanSource}</Pill>{scanError&&<div className="notice"><Info size={18}/>{scanError}</div>}</div><div className="panel"><SectionTitle title="Datos de la compra"/><div className="form-two"><label className="field">Comercio / sucursal detectada<select value={draftStore} onChange={e=>setDraftStore(e.target.value)}><option value="">No identificada</option>{stores.map(s=><option value={s.id} key={s.id}>{s.name} · {s.branch}</option>)}</select></label><label className="field">Fecha de compra<input type="date" value={draftDate} max={isoToday()} onChange={e=>setDraftDate(e.target.value)}/></label></div><div className="notice"><Info size={18}/> Una compra sin sucursal identificada se guarda en el historial, pero no modifica precios de una tienda concreta.</div><SectionTitle title="Artículos reconocidos" action={<button className="text-action" onClick={()=>setDraftRows(prev=>[...prev,{productId:'',label:'',qty:1,unitPrice:0}])}><Plus size={16}/> Añadir línea</button>}/>{draftRows.map((r,i)=><div className="receipt-row" key={i}><label className="field grow">Producto<select value={r.productId} onChange={e=>updateDraft(i,'productId',e.target.value)}><option value="">Sin identificar</option>{products.map(p=><option value={p.id} key={p.id}>{p.name} · {p.brand} · {p.size}</option>)}</select></label><label className="field tiny">Cantidad<input type="number" min="1" step="1" value={r.qty} onChange={e=>updateDraft(i,'qty',Math.max(1,Number(e.target.value)))}/></label><label className="field tiny">P. unitario<input type="number" min="0" step="0.01" value={r.unitPrice} onChange={e=>updateDraft(i,'unitPrice',Number(e.target.value))}/></label><button className="icon-button danger" aria-label="Eliminar línea" onClick={()=>setDraftRows(prev=>prev.filter((_,j)=>i!==j))}><X size={18}/></button></div>)}<div className="receipt-total"><span>Total de artículos identificados</span><strong>{money(draftRows.reduce((sum,r)=>sum+Math.max(r.qty,0)*Math.max(r.unitPrice,0),0))}</strong></div><div className="action-row"><button className="button subtle" onClick={()=>setScanState('upload')}><ArrowLeft size={17}/> Volver</button><button className="button blue" onClick={saveReceipt}>Registrar compra <ArrowRight size={17}/></button></div></div></div>:<div className="success-card"><span className="big-check"><CheckCircle2 size={58}/></span><span className="eyebrow">¡REGISTRO COMPLETO!</span><h2>¡Bien hecho! Cada ticket suma.</h2><p>Tu compra ahora forma parte de tu historial y tus datos de prueba ya están conectados al comparador.</p><div className="points-gained"><Coins size={27}/><strong>+{lastEarned} puntos</strong><small>{lastEarned?'+10 por ticket y +2 por producto distinto (hasta 5).':'Esta compra no reúne las condiciones para bonificación.'}</small></div><p>Saldo actual: <b>{points} puntos</b></p><div className="action-row center"><button className="button subtle" onClick={()=>navigate('history')}>Ver historial</button><button className="button blue" onClick={()=>navigate('benefits')}>Explorar recompensas <ArrowRight size={17}/></button></div><button className="text-action" onClick={()=>setScanState('upload')}>Registrar otro ticket</button></div>}</>;
 if(page==='history')return <><div className="page-head"><div><span className="eyebrow">REGISTRO PERSONAL</span><h1>Mis compras</h1><p>Consulta tickets, importes y productos registrados.</p></div><button className="button subtle" onClick={openScan}><Plus size={17}/> Nuevo ticket</button></div>{receipts.length?<div className="history-list">{receipts.map(r=><details className="history-item" key={r.id}><summary><span className="transaction-icon"><ReceiptText/></span><span className="history-title"><b>{r.merchant}</b><small>{r.date} · {r.items.length} productos · {r.source}</small></span><span className="history-money"><b>{money(r.total)}</b><small>+{r.points} puntos</small></span><ChevronDown size={19}/></summary><div className="history-detail"><Pill color={r.storeId?'green':'amber'}>{r.storeId?'Sucursal identificada':'Sucursal desconocida'}</Pill>{r.items.map((it,i)=><div className="history-line" key={i}><span>{lookup(it.productId)?.name} · {it.qty} × {money(it.unitPrice)}</span><strong>{money(it.qty*it.unitPrice)}</strong></div>)}</div></details>)}</div>:<Empty icon={History} title="Aún no hay compras" desc="Escanea tu primer ticket para construir tu historial de consumo." action={<button className="button blue" onClick={openScan}>Escanear un ticket</button>}/>}</>;
 if(page==='alerts')return <><div className="page-head"><div><span className="eyebrow">LO QUE TE IMPORTA, A TIEMPO</span><h1>Alertas de precios</h1><p>Sigue productos frecuentes y consulta precios observados en sucursales.</p></div><button className="button subtle" onClick={()=>setAlertsSeen(true)}><Check size={17}/> Marcar como vistas</button></div><section className="alerts-overview"><div className="alerts-overview-copy"><span className="overline">TUS PRECIOS, MÁS CERCA</span><h2>Ten a la vista lo que compras seguido.</h2><p>Consulta los productos que sigues y revisa las observaciones disponibles antes de ir al supermercado.</p></div><div className="alerts-overview-art" aria-hidden="true"><div className="alert-graphic"><div className="alert-graphic-top"><span>Seguimiento de precios</span><TrendingDown size={17}/></div><div className="alert-graphic-bars"><i/><i/><i/><i/><i/></div><div className="alert-graphic-caption">Gráfico ilustrativo · sin datos reales</div></div></div></section><div className="notice"><Info size={18}/> Las alertas se calculan con los datos del prototipo. No se realizan notificaciones push ni seguimiento de ubicación en segundo plano.</div><SectionTitle eyebrow={`${followed.length} PRODUCTOS SEGUIDOS`} title="Productos que sigo" action={<button className="text-action" onClick={()=>navigate('compare')}>Explorar catálogo <ArrowRight size={15}/></button>}/>{followed.length?<div className="alerts-list">{followed.map(id=>{const p=lookup(id);if(!p)return null;const available=stores.map(s=>({store:s,price:priceFor(id,s.id)})).filter(x=>!!x.price).sort((a,b)=>a.price!.value-b.price!.value);const low=available[0];return <div className="alert-card" key={id}><ProductArt emoji={p.emoji} small/><div className="alert-main"><b>{p.name}</b><small>{p.brand} · {p.size}</small>{low&&<span className="price-line"><TrendingDown size={15}/> Precio más bajo registrado: <b>{money(low.price!.value)}</b> en {low.store.name}</span>}</div><button className="icon-button" aria-label="Dejar de seguir" title="Dejar de seguir" onClick={()=>setFollowed(prev=>prev.filter(x=>x!==id))}><Heart size={19} fill="#e9657a" color="#e9657a"/></button></div>})}</div>:<Empty icon={Bell} title="No sigues ningún producto" desc="Selecciona tus productos de interés para consultar oportunidades de ahorro."/>}<SectionTitle eyebrow="PERSONALIZA" title="Añadir seguimiento"/><div className="follow-grid">{products.filter(p=>!followed.includes(p.id)).slice(0,8).map(p=><button key={p.id} className="follow-item" onClick={()=>{setFollowed(prev=>[...prev,p.id]);notify('Ahora sigues '+p.name)}}><ProductArt emoji={p.emoji} small/><span>{p.name}<small>{p.size}</small></span><Plus size={17}/></button>)}</div>{alertsSeen&&<p className="muted small">Alertas marcadas como consultadas.</p>}</>;
 if(page==='benefits')return <><div className="page-head"><div><span className="eyebrow">RECOMPENSAS POR PARTICIPAR</span><h1>Beneficios cerca de ti</h1><p>Canjea tus puntos por promociones de comercios locales.</p></div><Pill color="amber">PROMOCIONES FICTICIAS</Pill></div><div className="points-hero"><div><span>MI SALDO DISPONIBLE</span><strong>{points}<small> puntos</small></strong><p>Acumula puntos al registrar tickets válidos, no por gastar más.</p></div><div className="points-illustration"><Coins size={74} strokeWidth={1.3}/></div></div><SectionTitle eyebrow="DISPONIBLES EN DEMOSTRACIÓN" title="Promociones para ti"/><div className="coupon-grid">{coupons.map(c=><div className="coupon-card" key={c.id}><div className="coupon-image"><span>{c.emoji}</span><Pill color="blue">{c.tag}</Pill></div><div className="coupon-body"><span className="eyebrow">{c.merchant}</span><h3>{c.title}</h3><p>{c.description}</p><div className="coupon-bottom"><strong><Coins size={16}/>{c.cost} pts</strong><span>{Math.max(0,c.stock-c.claimed)} disponibles</span></div><button className="button blue wide" onClick={()=>setShowCoupon(c)}>{pendingClaim(c.id)?'Ver condiciones':'Ver beneficio'} <ArrowRight size={16}/></button></div></div>)}</div><SectionTitle eyebrow="MIS BENEFICIOS" title="Cartera de cupones"/>{claims.length?<div className="claim-list">{claims.map(c=>{const coupon=coupons.find(p=>p.id===c.couponId);return <div className="claim-row" key={c.id}><span className="claim-icon"><TicketPercent size={21}/></span><div><b>{coupon?.title||'Cupón'}</b><small>{coupon?.merchant} · {c.status==='reserved'?'Reserva activa (máx. 24 h)':c.status==='used'?'Canje utilizado':'Vencido'}</small><code>{c.code}</code></div><Pill color={c.status==='reserved'?'green':'gray'}>{c.status==='reserved'?'Disponible':c.status==='used'?'Usado':'Vencido'}</Pill></div>})}</div>:<div className="mini-empty horizontal"><Wallet size={25}/><span>Aún no reclamas cupones. ¡Explora las promociones!</span></div>}<div className="notice"><ShieldCheck size={19}/> Recompensas y comercios son de demostración. Los cupones no son válidos en establecimientos reales y los puntos no equivalen a efectivo.</div></>;
 return <><div className="page-head"><div><span className="eyebrow">TU ESPACIO</span><h1>Mi perfil</h1><p>Controla tus datos de demostración y explora CesTick.</p></div></div><div className="profile-grid"><div className="panel profile-card"><span className="profile-avatar"><UserRound size={31}/></span><h2>Explorador CesTick</h2><p>Cuenta de prueba · Cancún, Quintana Roo</p><div className="profile-stats"><div><strong>{receipts.length}</strong><small>Tickets</small></div><div><strong>{points}</strong><small>Puntos</small></div><div><strong>{claims.length}</strong><small>Cupones</small></div></div></div><div className="panel"><SectionTitle title="Preferencias"/><div className="setting-line"><MapPin size={20}/><div><b>Ubicación de referencia</b><small>Cancún · zona de ejemplo, sin geolocalización obligatoria</small></div></div><div className="setting-line"><ShieldCheck size={20}/><div><b>Privacidad</b><small>Datos de la demostración guardados solo en este navegador.</small></div></div><div className="setting-line"><BadgeCheck size={20}/><div><b>Modo de demostración</b><small>Sin pagos, campañas reales ni precios garantizados.</small></div></div><button className="button subtle" onClick={reset}><RotateCcw size={17}/> Restaurar demostración</button></div></div></>;
 };
 const renderMerchant=()=>{
 if(merchantPage==='overview')return <><div className="page-head"><div><span className="eyebrow">PORTAL PARA COMERCIOS · DEMOSTRACIÓN</span><h1>Hola, negocio local 👋</h1><p>Administra beneficios y llega a más personas en tu comunidad.</p></div><button className="button blue" onClick={()=>merchantNavigate('coupons')}><Plus size={17}/> Crear campaña</button></div><div className="home-metrics"><div className="metric"><span className="metric-icon blue"><TicketPercent size={22}/></span><span>Campañas creadas</span><strong>{coupons.length}</strong><small>Promociones de demostración</small></div><div className="metric"><span className="metric-icon aqua"><Wallet size={22}/></span><span>Cupones reclamados</span><strong>{claims.length}</strong><small>Reservas generadas</small></div><div className="metric"><span className="metric-icon lavender"><BadgeCheck size={22}/></span><span>Canjes validados</span><strong>{claims.filter(x=>x.status==='used').length}</strong><small>Confirmaciones registradas</small></div></div><div className="merchant-banner"><div><Pill>PORTAL COMERCIAL</Pill><h2>Promociones con condiciones claras.</h2><p>Define cupos, vigencia, compra mínima y beneficios. La publicidad y los descuentos mantienen presupuestos separados.</p><button className="button white" onClick={()=>merchantNavigate('coupons')}>Crear cupón <ArrowRight size={17}/></button></div><span className="merchant-banner-icon"><StoreIcon size={74} strokeWidth={1.35}/></span></div><SectionTitle eyebrow="OPERACIÓN" title="Acciones principales"/><div className="merchant-quick"><button onClick={()=>merchantNavigate('coupons')}><TicketPercent/><b>Crear cupón</b><small>Publica una promoción demo</small><ArrowRight size={17}/></button><button onClick={()=>merchantNavigate('ads')}><Megaphone/><b>Publicidad</b><small>Simula una campaña patrocinada</small><ArrowRight size={17}/></button><button onClick={()=>merchantNavigate('redeem')}><BadgeCheck/><b>Validar canje</b><small>Usa un código reclamado</small><ArrowRight size={17}/></button></div></>;
 if(merchantPage==='coupons')return <><div className="page-head"><div><span className="eyebrow">CAMPAÑAS DE BENEFICIOS</span><h1>Cupones para tu comunidad</h1><p>Crea campañas ficticias y observa cómo se conectan con el consumidor.</p></div></div><div className="merchant-split"><div className="panel"><SectionTitle title="Crear cupón"/><div className="form-stack"><label className="field">Nombre del negocio<input placeholder="Ej. Café Brisa" value={merchantDraft.name} onChange={e=>setMerchantDraft(p=>({...p,name:e.target.value}))}/></label><label className="field">Beneficio<input placeholder="Ej. $50 de descuento" value={merchantDraft.title} onChange={e=>setMerchantDraft(p=>({...p,title:e.target.value}))}/></label><div className="form-two"><label className="field">Compra mínima (MXN)<input type="number" min="0" value={merchantDraft.minimum} onChange={e=>setMerchantDraft(p=>({...p,minimum:e.target.value}))}/></label><label className="field">Costo en puntos<select value={merchantDraft.cost} onChange={e=>setMerchantDraft(p=>({...p,cost:e.target.value}))}><option value="120">120 pts</option><option value="160">160 pts</option><option value="200">200 pts</option></select></label></div><div className="form-two"><label className="field">Máximo de canjes<input type="number" min="1" value={merchantDraft.stock} onChange={e=>setMerchantDraft(p=>({...p,stock:e.target.value}))}/></label><label className="field">Vigencia<input type="date" value={merchantDraft.expires} onChange={e=>setMerchantDraft(p=>({...p,expires:e.target.value}))}/></label></div><div className="notice"><Info size={18}/> Ejemplo: descuento de $50 × 10 cupones = exposición máxima nominal de $500. El descuento lo financia el negocio, no CesTick.</div><button className="button blue wide" onClick={makeCoupon}>Publicar cupón de demostración <ArrowRight size={17}/></button></div></div><div className="panel"><SectionTitle title="Mis campañas"/><div className="campaigns">{coupons.map(c=><div className="campaign" key={c.id}><span className="campaign-emoji">{c.emoji}</span><div><b>{c.title}</b><small>{c.merchant}</small><small>{c.claimed}/{c.stock} reclamados · {c.cost} puntos</small></div><Pill color="green">Demo</Pill></div>)}</div></div></div></>;
 if(merchantPage==='ads')return <><div className="page-head"><div><span className="eyebrow">PUBLICIDAD IDENTIFICADA</span><h1>Campañas patrocinadas</h1><p>Los anuncios son independientes del ranking orgánico del comparador.</p></div></div><div className="merchant-split"><div className="panel"><SectionTitle title="Simulación de anuncio"/><div className="form-stack"><label className="field">Negocio<input value="Café Brisa (demostración)" readOnly/></label><label className="field">Mensaje del anuncio<input value="Un café rico para acompañar tu día" readOnly/></label><label className="field">Periodo<input value="7 días · escenario de ejemplo" readOnly/></label><div className="notice"><Info size={18}/> Ejemplo conceptual: tarifa publicitaria de $250 por 7 días. No hay cobro ni compra de publicidad real. El descuento de cada cupón se calcula por separado.</div><button className={'button '+(adActive?'subtle':'blue')} onClick={()=>{setAdActive(!adActive);setMerchantMessage(adActive?'Anuncio de demostración pausado.':'Anuncio de demostración activado.')}}>{adActive?'Pausar anuncio demo':'Activar anuncio demo'}</button></div></div><div className="panel"><SectionTitle title="Vista previa en la app"/><div className="ad-preview"><Pill color="gray">Patrocinado · demostración</Pill><span>☕</span><h3>Café Brisa</h3><p>Un café rico para acompañar tu día. Descubre nuestros beneficios.</p><span className="ad-link">Conoce el negocio <ArrowUpRight size={16}/></span></div><p className="muted small">Estado: {adActive?'activo':'pausado'} · impresiones y clics no medidos.</p></div></div></>;
 if(merchantPage==='redeem')return <><div className="page-head"><div><span className="eyebrow">VALIDACIÓN EN MOSTRADOR</span><h1>Canjear un cupón</h1><p>Comprueba un código reclamado y márcalo como utilizado en la demo.</p></div></div><div className="merchant-split"><div className="panel"><SectionTitle title="Validar código"/><p className="muted">Primero reclama un cupón desde Beneficios con la cuenta de prueba. Después introduce su código aquí.</p><label className="field">Código de cupón<input placeholder="CT-XXXXXX" value={merchantCode} onChange={e=>setMerchantCode(e.target.value.toUpperCase())}/></label><div className="notice"><ShieldCheck size={18}/> El comercio debe comprobar que se cumplió la compra mínima y que el beneficio corresponde a la promoción.</div><button className="button blue wide" onClick={redeem}><BadgeCheck size={17}/> Validar uso (demo)</button></div><div className="panel"><SectionTitle title="Movimientos de canje"/>{claims.length?claims.map(c=><div className="claim-row" key={c.id}><span className="claim-icon"><TicketPercent size={20}/></span><div><b>{coupons.find(x=>x.id===c.couponId)?.title}</b><code>{c.code}</code></div><Pill color={c.status==='used'?'gray':'green'}>{c.status==='used'?'Usado':'Reservado'}</Pill></div>):<Empty icon={TicketPercent} title="Sin canjes todavía" desc="Reclama un cupón desde el perfil del consumidor para probar este módulo."/>}</div></div></>;
 return <><div className="page-head"><div><span className="eyebrow">TU PRESENCIA EN CESTICK</span><h1>Mi negocio</h1><p>Datos de ejemplo para la ficha pública de un establecimiento local.</p></div></div><div className="merchant-split"><div className="panel"><span className="business-cover">☕</span><h2>Café Brisa</h2><Pill color="amber">Negocio ficticio</Pill><p className="muted">Café y repostería local. Una pausa bonita en tu día.</p><div className="setting-line"><MapPin/><div><b>Zona de ejemplo</b><small>Centro, Cancún, Quintana Roo</small></div></div><div className="setting-line"><Clock3/><div><b>Horario ilustrativo</b><small>Lunes a sábado · 8:00–19:00</small></div></div></div><div className="panel"><SectionTitle title="Cómo funciona CesTick para negocios"/><div className="how-list"><div><span>01</span><p>Publicas una ficha y creas cupones con cupos y condiciones.</p></div><div><span>02</span><p>Las personas reclaman beneficios con puntos obtenidos por tickets.</p></div><div><span>03</span><p>Validas el código al aplicar el descuento en mostrador.</p></div><div><span>04</span><p>Puedes simular un anuncio patrocinado independiente de las comparaciones.</p></div></div></div></div></>;
 };
 const currentLabel=mode==='consumer'?({home:'Inicio',compare:'Comparar',scan:'Escanear ticket',alerts:'Alertas',benefits:'Beneficios',basket:'Mi canasta',history:'Mis compras',profile:'Mi perfil'} as const)[page]:({overview:'Resumen',coupons:'Cupones',ads:'Publicidad',redeem:'Canjes',business:'Mi negocio'} as const)[merchantPage];
 return <div className="app-shell ux-shell">
  <header className="site-header"><div className="header-inner">
    <button className="header-brand" onClick={()=>navigate('home')} aria-label="Ir al inicio de CesTick"><Logo/></button>
    <nav className="desktop-links" aria-label="Navegación principal">
      {mode==='consumer'?<><button className={page==='home'?'selected':''} onClick={()=>navigate('home')}>Inicio</button><button className={page==='compare'?'selected':''} onClick={()=>navigate('compare')}>Explorar precios</button><button className={page==='basket'?'selected':''} onClick={()=>navigate('basket')}>Mi canasta <span className="nav-count">{basket.length}</span></button><button className={page==='alerts'?'selected':''} onClick={()=>navigate('alerts')}>Alertas</button><button className={page==='benefits'?'selected':''} onClick={()=>navigate('benefits')}>Beneficios</button></>:merchantNav.map(n=><button key={n.id} className={merchantPage===n.id?'selected':''} onClick={()=>merchantNavigate(n.id)}>{n.text}</button>)}
    </nav>
    <div className="header-actions"><span className="header-demo">Prototipo · 2026</span>{mode==='consumer'&&<button className="header-scan" onClick={openScan}><ScanLine size={17}/> Escanear ticket</button>}<button className="header-account" aria-label="Abrir menú de usuario" aria-expanded={mobileMenu} onClick={()=>setMobileMenu(v=>!v)}><UserRound size={18}/><ChevronDown size={13}/></button></div>
  </div></header>
  {mobileMenu&&<><button className="menu-scrim" aria-label="Cerrar menú" onClick={()=>setMobileMenu(false)}/><div className="account-menu" role="menu"><span className="menu-caption">MI CUENTA</span><button onClick={()=>navigate('history')}><History size={17}/> Historial de compras</button><button onClick={()=>navigate('profile')}><UserRound size={17}/> Preferencias y perfil</button><button onClick={()=>navigate('basket')}><ShoppingBasket size={17}/> Mi canasta</button><div className="menu-line"/><span className="menu-caption">MODO DE USO</span><button className={mode==='consumer'?'mode-selected':''} onClick={()=>{setMode('consumer');setMobileMenu(false);navigate('home')}}><UserRound size={17}/> Soy consumidor</button><button className={mode==='merchant'?'mode-selected':''} onClick={()=>merchantNavigate('overview')}><StoreIcon size={17}/> Soy comercio</button></div></>}
  <main className="ux-main">{mode==='consumer'?renderConsumer():renderMerchant()}<footer className="ux-footer"><span><b>CesTick</b> · Code Queens · Tucanthon 2026</span><span>Precios y promociones de demostración · Cancún, México</span></footer></main>
  <nav className="ux-bottom-nav" aria-label="Navegación móvil">{mode==='consumer'?nav.map(n=><button key={n.id} className={(page===n.id?'current ':'')+(n.id==='scan'?'primary-tab':'')} onClick={()=>n.id==='scan'?openScan():navigate(n.id)}>{n.id==='scan'?<span className="mobile-scan-circle"><ScanLine size={22}/></span>:<n.icon size={20}/>}<small>{n.text}</small></button>):merchantNav.map(n=><button key={n.id} className={merchantPage===n.id?'current':''} onClick={()=>merchantNavigate(n.id)}><n.icon size={20}/><small>{n.text}</small></button>)}</nav>
  {showCoupon&&<div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Detalle del cupón"><div className="modal"><button className="modal-close" aria-label="Cerrar" onClick={()=>setShowCoupon(null)}><X size={22}/></button><div className="modal-art">{showCoupon.emoji}</div><Pill color="amber">PROMOCIÓN FICTICIA</Pill><h2>{showCoupon.title}</h2><p>{showCoupon.merchant} · {showCoupon.description}</p><div className="modal-details"><div><span>Costo</span><b>{showCoupon.cost} puntos</b></div><div><span>Compra mínima</span><b>{money(showCoupon.minimum)}</b></div><div><span>Vigente hasta</span><b>{showCoupon.expires}</b></div><div><span>Cupos restantes</span><b>{showCoupon.stock-showCoupon.claimed}</b></div></div><p className="footnote">El reclamo descuenta puntos y reserva un cupo por 24 horas. Esta demostración no otorga descuentos reales.</p><button className="button blue wide" disabled={points<showCoupon.cost||showCoupon.claimed>=showCoupon.stock||!!pendingClaim(showCoupon.id)||showCoupon.expires<isoToday()} onClick={()=>claimCoupon(showCoupon)}>{pendingClaim(showCoupon.id)?'Ya reclamado':points<showCoupon.cost?'Puntos insuficientes':'Reclamar por '+showCoupon.cost+' puntos'} <ArrowRight size={17}/></button></div></div>}{merchantMessage&&mode==='merchant'&&<div className="notice floating-notice"><Info size={18}/>{merchantMessage}<button onClick={()=>setMerchantMessage('')}><X size={16}/></button></div>}{toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}</div>;
}
export default App;
